def transform(grid):
    """Recolor occurrences of the non-background marker shape in zero cells."""
    h, w = len(grid), len(grid[0])
    marker = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 9]
    r0, r1 = min(r for r, c in marker), max(r for r, c in marker)
    c0, c1 = min(c for r, c in marker), max(c for r, c in marker)
    shape = {(r-r0, c-c0) for r, c in marker}
    out = [row[:] for row in grid]
    for r in range(h-(r1-r0+1)+1):
        for c in range(w-(c1-c0+1)+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = 9
    return out
